var idTokenSourceFactory = func(ctx context.Context, cfg impersonate.IDTokenConfig) (oauth2.TokenSource, error) {
	return impersonate.IDTokenSource(ctx, cfg)
}

// providerTokenFunc は認証モードに応じて、要求ごとに送る Bearer 資格情報を返す関数を作る。
//   - fake: --principal / LAPPDS_PROVIDER_PRINCIPAL の値（email）をそのまま送る。
//   - iam : LAPPDS_INVOKER_SA の invoker SA を impersonate し、aud=audience（サービス URL）の
//     ID トークンを generateIdToken で発行して送る（[設計 06]）。ユーザー資格情報
//     （authorized_user）からは aud 固定の ID トークンを直接作れないため impersonation を使う。
func providerTokenFunc(mode auth.Mode, audience string) func(context.Context) (string, error) {
	if mode == auth.ModeFake {
		p := providerPrincipal()
		return func(context.Context) (string, error) { return p, nil }
	}
	return func(ctx context.Context) (string, error) {
		sa := os.Getenv("LAPPDS_INVOKER_SA")
		if sa == "" {
			return "", fmt.Errorf("LAPPDS_INVOKER_SA が未設定です（impersonate する invoker SA を指定してください。管理者から受け取る terraform output cli_invoker_sa の値。[設計 06]）")
		}
		ts, err := idTokenSourceFactory(ctx, impersonate.IDTokenConfig{
			TargetPrincipal: sa,
			Audience:        audience,
			IncludeEmail:    true,
		})
		if err != nil {
			return "", fmt.Errorf("ID トークン取得元の初期化に失敗しました（gcloud auth application-default login と invoker SA への tokenCreator を確認してください）: %w", err)
		}
		tok, err := ts.Token()
		if err != nil {
			return "", fmt.Errorf("ID トークンの取得に失敗しました: %w", err)
		}
