new_hdr='''// parseJudgmentFlow は Markdown の判定フローを読み、文書の構造を確かめる。表の
// 見分けは見出し行の先頭セルで行う — 「ID」なら決定表、「始点」なら遷移表。それ以外の
// 表は読まない。見出しの直後の区切り行から、次に表でない行が来るまでを本体とする。
//
// 第 2 の戻り値は文書の構造の問題。構造とは、表の意味 (種類ごとの規則・遷移・
// 到達可能性) より手前の、読むための前提そのもの — ``` のフェンスが閉じている、
// フェンスの中の行を表として読まない、決定表と遷移表が 1 つずつ、ID が形に合う、
// 同じ ID の行が無い、表示名が図のラベルに出せる文字だけ。前提はここで一度だけ
// 確かめ、後の段階 (judgmentFlowTableProblems・render・write) には確かめた結果だけを
// 渡す。段階ごとに自分の前提で読むと、確かめなかった前提の数だけ別々の欠陥になる
// (回 3 の指摘 1〜3: 閉じの無いフェンスで生成が panic した、1 行目の ID が壊れると
// 到達可能性の誤報が連鎖した、フェンスの中の用例が正本として読まれた)。
//
// 形の合わない ID と重複した行は Nodes に入れない。返す doc が完全なのは構造の問題が
// 0 件のときだけで、呼び出し側は問題があれば表の意味を検査せず、図も生成しない。
func parseJudgmentFlow(data []byte) (judgmentFlowDoc, []string) {
	var doc judgmentFlowDoc
	var problems []string
	add := func(format string, args ...any) {
		problems = append(problems, judgmentFlowPath+": "+fmt.Sprintf(format, args...))
	}
	doc.lines = strings.Split(string(data), "\\n")
	doc.DiagramStart, doc.DiagramEnd = -1, -1
	fenceLine := -1    // 開いているフェンスの行 (0 始まり)。-1 なら開いていない
	inMermaid := false // 開いているフェンスが図 (最初の mermaid) か
	var diagram []string
	table := ""                   // 読んでいる表の種類 ("ID" / "始点" / "")
	tableAt := map[string]int{}   // 表の種類 → 見出しの行番号 (1 始まり)。2 つ目を報告する
	idAt := map[string]int{}      // ID → 決定表の行番号 (1 始まり)。重複を報告する
	for i, line := range doc.lines {
		trimmed := strings.TrimSpace(line)
		if fenceLine >= 0 {
			if strings.HasPrefix(trimmed, "```") {
				if inMermaid {
					doc.DiagramEnd = i
					doc.Diagram = strings.Join(diagram, "\\n")
				}
				fenceLine, inMermaid = -1, false
				continue
			}
			if inMermaid {
				diagram = append(diagram, line)
			}
			continue
		}
		if strings.HasPrefix(trimmed, "```") {
			// フェンスはすべて追跡する。図として取るのは最初の mermaid だけで、
			// 他のフェンス (用例の ```text など) の中は表として読まない。
			fenceLine = i
			table = ""
			if strings.HasPrefix(trimmed, "```mermaid") && !doc.HasDiagram {
				inMermaid = true
				doc.HasDiagram = true
				doc.DiagramStart = i
			}
			continue
		}
		if !strings.HasPrefix(trimmed, "|") {
